#!/usr/bin/env node
// Creates the links Devbook needs in a project, from .devbook/devbook.manifest.json and the files AGENTS.md lists:
// path-scoped rules into .claude/rules and .github/instructions, and skills into .claude/skills. Idempotent: run it
// again after every upgrade. Where symlinks don't work (Windows without Developer Mode, core.symlinks=false), it
// copies the files with a "Generated by Devbook" header instead, and refreshes those copies on the next run.
//
//   node .devbook/skills/devbook-setup/scripts/link.mjs [--dry-run] [--copy] [--prune] [--root <dir>] [--assistants claude,copilot]
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';
import {
	cpSync,
	existsSync,
	lstatSync,
	mkdirSync,
	readFileSync,
	readdirSync,
	readlinkSync,
	rmSync,
	symlinkSync,
	writeFileSync,
	realpathSync,
} from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { parseArgs } from 'node:util';
import { DEFAULT_ASSISTANTS, GENERATED, MANAGED_DIRS, plan, withHeader } from './lib.mjs';

/** The relative symlink target for `dest` pointing at `source` (both relative to root). */
export const target = (dest, source) => relative(dirname(dest), source);

/** True when the repository can hold symlinks: git doesn't turn them off and the file system allows them. */
export function symlinksWork(root) {
	try {
		const value = execFileSync('git', ['config', '--get', 'core.symlinks'], { cwd: root, encoding: 'utf8' }).trim();
		if (value === 'false') return false;
	} catch {
		// unset: git's default for this platform
	}
	const probe = join(root, `.devbook-symlink-probe-${process.pid}`);
	try {
		symlinkSync('.devbook', probe);
		rmSync(probe);
		return true;
	} catch {
		return false;
	}
}

/** What a link or copy at `dest` is now: 'missing', 'ok', 'outdated' (Devbook's, refresh it) or 'foreign' (the project's). */
export function status(root, { dest, source, kind }, mode) {
	const abs = join(root, dest);
	let stat;
	try {
		stat = lstatSync(abs);
	} catch {
		return 'missing';
	}
	if (stat.isSymbolicLink()) {
		const ok = readlinkSync(abs) === target(dest, source) && existsSync(abs);
		return ok && mode === 'link' ? 'ok' : 'outdated';
	}
	const file = kind === 'dir' ? join(abs, 'SKILL.md') : abs;
	const text = existsSync(file) ? readFileSync(file, 'utf8') : '';
	if (!text.includes(GENERATED)) return 'foreign';
	if (mode === 'link') return 'outdated';
	const expected = withHeader(readFileSync(join(root, source, kind === 'dir' ? 'SKILL.md' : ''), 'utf8'), source);
	return text === expected ? 'ok' : 'outdated';
}

function write(root, { dest, source, kind }, mode) {
	const abs = join(root, dest);
	rmSync(abs, { recursive: true, force: true });
	mkdirSync(dirname(abs), { recursive: true });
	if (mode === 'link') return symlinkSync(target(dest, source), abs, kind === 'dir' ? 'dir' : 'file');
	if (kind === 'dir') {
		cpSync(join(root, source), abs, { recursive: true, dereference: true });
		const skill = join(abs, 'SKILL.md');
		writeFileSync(skill, withHeader(readFileSync(skill, 'utf8'), source));
	} else writeFileSync(abs, withHeader(readFileSync(join(root, source), 'utf8'), source));
}

/** Devbook entries in the managed folders that the plan no longer lists. */
export function stale(root, entries) {
	const wanted = new Set(entries.map((e) => e.dest));
	const out = [];
	for (const dir of MANAGED_DIRS) {
		if (!existsSync(join(root, dir))) continue;
		for (const name of readdirSync(join(root, dir)).filter((n) => n.startsWith('devbook-'))) {
			const dest = `${dir}/${name}`;
			if (!wanted.has(dest)) out.push(dest);
		}
	}
	return out;
}

/** Run the plan. Returns the actions taken (or, with dryRun, that would be taken). */
export function link(root, { dryRun = false, copy = false, prune = false, assistants = DEFAULT_ASSISTANTS } = {}) {
	const entries = plan(root, { assistants });
	const mode = copy || !symlinksWork(root) ? 'copy' : 'link';
	const actions = [];
	for (const entry of entries) {
		const now = status(root, entry, mode);
		if (now === 'ok') actions.push({ ...entry, action: 'ok' });
		else if (now === 'foreign') actions.push({ ...entry, action: 'skipped: a file not made by Devbook is in the way' });
		else {
			if (!dryRun) write(root, entry, mode);
			actions.push({ ...entry, action: now === 'missing' ? `created (${mode})` : `refreshed (${mode})` });
		}
	}
	for (const dest of stale(root, entries)) {
		if (prune && !dryRun) rmSync(join(root, dest), { recursive: true, force: true });
		actions.push({
			dest,
			action: prune ? 'removed (no longer chosen)' : 'stale: no longer chosen; rerun with --prune to remove',
		});
	}
	return { mode, actions };
}

// Compare real paths: on macOS /var is a link to /private/var, so a plain URL comparison can miss.
if (process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url)) {
	const { values } = parseArgs({
		options: {
			'dry-run': { type: 'boolean', default: false },
			copy: { type: 'boolean', default: false },
			prune: { type: 'boolean', default: false },
			root: { type: 'string', default: '.' },
			assistants: { type: 'string', default: DEFAULT_ASSISTANTS.join(',') },
		},
	});
	try {
		const { mode, actions } = link(resolve(values.root), {
			dryRun: values['dry-run'],
			copy: values.copy,
			prune: values.prune,
			assistants: values.assistants.split(',').map((s) => s.trim()),
		});
		if (mode === 'copy' && !values.copy)
			console.log('Symlinks are not available here, so files are copied with a generated-file header.');
		for (const a of actions) console.log(`${a.dest}: ${a.action}`);
		if (values['dry-run']) console.log('Dry run: nothing written.');
		if (actions.some((a) => a.action.startsWith('skipped'))) process.exit(1);
	} catch (error) {
		console.error(error.message);
		process.exit(2);
	}
}
